//! Deluxe — a Level-Loc-style crushing limiter with a distortion stage.
//!
//! A clean-room recreation of a well-known "Devil" limiter plug-in's
//! algorithm from black-box measurements of it: the same controls
//! (Crush, Crunch, Darkness, Release, Mix) doing the same things, aimed
//! at sounding the same rather than nulling. The measured constants live
//! in [`crate::deluxe_tables`] (generated by the saturator-models tools).
//!
//! What measurement showed the reference to be:
//!
//! ```text
//!  x ─ A ─ ×crush ─ ×g ─┬─ ×crunch ─ f(·) ─ HP 9.45 Hz ─ D(darkness) ─┐
//!                                 │                               ├─ mix ─ y
//!                     detector on (L+R)/2 ── g             dry ───┘
//! ```
//!
//! - `A` is the whole linear colour, *before* the curve: `H2/H1²` is flat
//!   from 100 Hz to 8 kHz, so nothing but a 9.45 Hz coupling high-pass
//!   follows the curve.
//! - Darkness is a steep low-pass after the curve — four coincident poles
//!   (an RC ladder) sliding from ~18 kHz down to ~2.4 kHz, then an
//!   overall level drop at the darkest settings. Measured in steady state
//!   (multitone) at twelve positions and crossfaded between neighbours.
//!   Its post-curve place is measured too: the detector never hears it,
//!   and it darkens the harmonics exactly as a filter after the curve
//!   would. (Single-impulse captures of it mislead: the reference's
//!   Darkness does not act as a fixed filter on an isolated spike.)
//! - `f` is a static asymmetric soft clip (rails ≈ +0.30 / −0.38),
//!   expansive at first, which is where the even harmonics come from.
//! - Crunch is gain *into the curve*, 3 dB per knob unit, after the
//!   detector tap — which is why it distorts instead of compressing.
//!   Crush is gain into the VCA along a measured 11-point taper.
//! - The detector is an *integrating* feedback detector on the stereo
//!   sum: a cap charged by a log-domain rectified (and 0.3 ms smoothed)
//!   excess of `|d|` over a
//!   threshold and discharged through a resistor, with gain reduction in
//!   dB proportional to the cap. That one mechanism gives the reference's
//!   ~10 ms overshoot after an onset, its dB-exponential release, its
//!   ≈ 15:1 static ratio, and the way it sits at the gain-reduction floor
//!   for hundreds of ms after a loud burst (the cap charged far past it).
//!   Release On discharges faster than Off.
//! - Mix is equal-power with a unity dry path.

use alloc::vec::Vec;
use core::f64::consts::{FRAC_PI_2, PI};

use crate::deluxe_tables as t;

/// The reference's controls, in its own units.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct DeluxeParams {
    /// 0..=10.
    pub crush: f64,
    /// 0..=10.
    pub crunch: f64,
    /// 500..=20000 Hz (20 kHz is the open position).
    pub darkness_hz: f64,
    /// 0..=100 %.
    pub mix: f64,
    /// The Release switch: On is the faster release.
    pub release_on: bool,
}

impl Default for DeluxeParams {
    fn default() -> Self {
        Self { crush: 0.0, crunch: 0.0, darkness_hz: 20_000.0, mix: 100.0, release_on: false }
    }
}

/// Crush knob (0..=10) → dB into the VCA.
#[must_use]
pub fn crush_db(knob: f64) -> f64 {
    let k = knob.clamp(0.0, 10.0);
    let lo = dsp_core::num::f64_to_index(libm::floor(k)).min(t::CRUSH_DB.len().saturating_sub(2));
    let frac = k - dsp_core::num::count_to_f64(lo);
    let a = t::CRUSH_DB.get(lo).copied().unwrap_or(0.0);
    let b = t::CRUSH_DB.get(lo.saturating_add(1)).copied().unwrap_or(a);
    (b - a) * frac + a
}

/// The static curve, from its measured table.
#[must_use]
pub fn curve(u: f64) -> f64 {
    crate::table::hermite(&t::CURVE, &t::CURVE_SLOPE, t::CURVE_UMAX, u)
}

/// The static picture of the stage, for a display.
///
/// The curve as driven by Crush and Crunch, for an input `x` in −1..1 (full
/// scale), normalised to the curve's rail. The limiter's gain riding is
/// dynamics, not a curve, so it is left out — this is what one cycle of a
/// transient meets.
#[must_use]
pub fn static_curve(p: &DeluxeParams, x: f64) -> f64 {
    let gain = libm::pow(10.0, (crush_db(p.crush) + t::CRUNCH_DB_PER_UNIT * p.crunch.clamp(0.0, 10.0)) / 20.0);
    let rail = curve(t::CURVE_UMAX).abs().max(curve(-t::CURVE_UMAX).abs());
    curve(0.25 * gain * x) / rail
}

/// A complex number, just enough of one for bilinear transforms.
#[derive(Clone, Copy, Debug)]
struct C(f64, f64);

impl C {
    const fn mul(self, o: Self) -> Self {
        Self(self.0 * o.0 - self.1 * o.1, self.0 * o.1 + self.1 * o.0)
    }

    fn div(self, o: Self) -> Self {
        let d = o.0 * o.0 + o.1 * o.1;
        Self((self.0 * o.0 + self.1 * o.1) / d, (self.1 * o.0 - self.0 * o.1) / d)
    }

    fn abs(self) -> f64 {
        libm::sqrt(self.0 * self.0 + self.1 * self.1)
    }
}

#[derive(Clone, Copy, Debug, Default)]
struct Biquad {
    c: [f64; 5],
    z1: f64,
    z2: f64,
}

impl Biquad {
    #[inline]
    fn run(&mut self, x: f64) -> f64 {
        let [b0, b1, b2, a1, a2] = self.c;
        let y = b0 * x + self.z1;
        self.z1 = b1 * x - a1 * y + self.z2;
        self.z2 = b2 * x - a2 * y;
        y
    }

    const fn reset(&mut self) {
        self.z1 = 0.0;
        self.z2 = 0.0;
    }
}

/// Analog roots (rad/s; conjugates implied for `im > 0`) → digital roots by
/// the bilinear transform at `sr`, expanded to real factors `(c1, c2)` of
/// `1 + c1 z⁻¹ + c2 z⁻²` (a lone real root gets `c2 = 0`). (The measured roots
/// came from an inverse bilinear at 48 kHz, so no pre-warping.)
fn factors(roots: &[(f64, f64)], sr: f64) -> Vec<(f64, f64)> {
    let k = 2.0 * sr;
    let mut out = Vec::new();
    let mut pending_real: Option<f64> = None;
    for &(re, im) in roots {
        let z = C(1.0 + re / k, im / k).div(C(1.0 - re / k, -im / k));
        if im > 0.0 {
            out.push((-2.0 * z.0, z.0 * z.0 + z.1 * z.1));
        } else if let Some(r) = pending_real.take() {
            out.push((-(r + z.0), r * z.0));
        } else {
            pending_real = Some(z.0);
        }
    }
    if let Some(r) = pending_real {
        out.push((-r, 0.0));
    }
    out
}

/// The open pre-curve response realised as biquads at `sr`.
fn pre_filter(measured: &t::PreFilter, sr: f64) -> Vec<Biquad> {
    realise(measured.zeros, measured.poles, measured.gain_1k, sr)
}

/// Analog zeros/poles → biquads at `sr`, scaled to `gain_1k` at 1 kHz.
fn realise(zeros: &[(f64, f64)], poles: &[(f64, f64)], gain_1k: f64, sr: f64) -> Vec<Biquad> {
    let zs = factors(zeros, sr);
    let ps = factors(poles, sr);
    let n = zs.len().max(ps.len());
    let mut secs: Vec<Biquad> = (0..n)
        .map(|i| {
            let (b1, b2) = zs.get(i).copied().unwrap_or((0.0, 0.0));
            let (a1, a2) = ps.get(i).copied().unwrap_or((0.0, 0.0));
            Biquad { c: [1.0, b1, b2, a1, a2], z1: 0.0, z2: 0.0 }
        })
        .collect();
    let at = |hz: f64| {
        let w = 2.0 * PI * hz / sr;
        let z1 = C(libm::cos(w), -libm::sin(w));
        let z2 = z1.mul(z1);
        secs.iter().fold(C(1.0, 0.0), |h, s| {
            let [b0, b1, b2, a1, a2] = s.c;
            let num = C(b0 + b1 * z1.0 + b2 * z2.0, b1 * z1.1 + b2 * z2.1);
            let den = C(1.0 + a1 * z1.0 + a2 * z2.0, a1 * z1.1 + a2 * z2.1);
            h.mul(num.div(den))
        })
    };
    // magnitude from the measurement at 1 kHz; polarity from 100 Hz, where
    // every measured response is near zero phase (a fitted numerator can
    // come out inverted, and crossfading an inverted neighbour cancels)
    let g = (gain_1k / at(1000.0).abs().max(1e-30)).copysign(at(100.0).0);
    if let Some(first) = secs.first_mut() {
        let [b0, b1, b2, a1, a2] = first.c;
        first.c = [b0 * g, b1 * g, b2 * g, a1, a2];
    }
    secs
}

/// Per-channel state: every Darkness position's pre-filter (all running, so
/// moving the knob never meets cold state) and the post-curve high-pass.
#[derive(Clone, Debug)]
struct Channel {
    pre: Vec<Biquad>,
    dark: Vec<Vec<Biquad>>,
    hp_x: f64,
    hp_y: f64,
}

impl Channel {
    fn new(sr: f64) -> Self {
        let dark = t::DARK.iter().map(|p| realise(p.zeros, p.poles, p.gain_1k, sr)).collect();
        Self { pre: pre_filter(&t::PRE, sr), dark, hp_x: 0.0, hp_y: 0.0 }
    }

    fn reset(&mut self) {
        self.pre.iter_mut().for_each(Biquad::reset);
        self.dark.iter_mut().flatten().for_each(Biquad::reset);
        self.hp_x = 0.0;
        self.hp_y = 0.0;
    }

    #[inline]
    fn pre(&mut self, x: f64) -> f64 {
        self.pre.iter_mut().fold(x, |v, s| s.run(v))
    }

    /// Darkness after the curve: every position's ratio runs (so moving the
    /// knob never meets cold state); positions `lo` and `lo + 1` (0 = open,
    /// the identity) are crossfaded by `w`.
    #[inline]
    fn dark(&mut self, x: f64, lo: usize, w: f64) -> f64 {
        let hi = lo.saturating_add(1);
        let open = if lo == 0 { (1.0 - w) * x } else { 0.0 };
        self.dark.iter_mut().enumerate().fold(open, |acc, (i, f)| {
            let y = f.iter_mut().fold(x, |v, s| s.run(v));
            let pos = i.saturating_add(1);
            if pos == lo {
                (1.0 - w) * y + acc
            } else if pos == hi {
                w * y + acc
            } else {
                acc
            }
        })
    }

    #[inline]
    fn post(&mut self, w: f64, b: f64, a: f64) -> f64 {
        let y = b * (w - self.hp_x) + a * self.hp_y;
        self.hp_x = w;
        self.hp_y = y;
        y
    }
}

/// Fastest the detector cap charges, dB of gain reduction per ms. Without a
/// limit, a single full-scale spike at high Crush charges thousands of dB
/// and holds the gain on its floor for seconds; the reference shrugs a
/// spike off yet still charges hundreds of dB over a 100 ms loud burst.
const CHARGE_MAX_DB_PER_MS: f64 = 5.0;

fn pole_ms(ms: f64, sample_rate: f64) -> f64 {
    if ms <= 0.0 { 0.0 } else { libm::exp(-1000.0 / (ms * sample_rate)) }
}

/// `k · ln(1 + e^(x/k))`: a smooth `max(0, x)`.
fn soft_over(x: f64, k: f64) -> f64 {
    let z = x / k;
    if z > 30.0 { x } else { k * libm::log1p(libm::exp(z)) }
}

/// The stereo Deluxe engine.
#[derive(Clone, Debug)]
pub struct Deluxe {
    sample_rate: f64,
    ch: [Channel; 2],
    crush: f64,
    crunch: f64,
    wet: f64,
    dry: f64,
    rel: f64,
    pre_lo: usize,
    pre_w: f64,
    charge: f64,
    charge_max: f64,
    theta: f64,
    smooth: f64,
    hp_b: f64,
    hp_a: f64,
    /// Rectified, smoothed detector input.
    m: f64,
    /// Detector cap: gain reduction in dB.
    vc: f64,
}

impl Deluxe {
    #[must_use]
    pub fn new(sample_rate: f64) -> Self {
        let k = libm::tan(PI * t::POST_HP_HZ / sample_rate);
        let mut s = Self {
            sample_rate,
            ch: [Channel::new(sample_rate), Channel::new(sample_rate)],
            crush: 1.0,
            crunch: 1.0,
            wet: 1.0,
            dry: 0.0,
            rel: 0.0,
            pre_lo: 0,
            pre_w: 0.0,
            charge: t::DET_CHARGE_PER_S / sample_rate,
            charge_max: CHARGE_MAX_DB_PER_MS * 1000.0 / sample_rate,
            theta: libm::pow(10.0, t::DET_THETA_DB / 20.0),
            smooth: 1.0 - pole_ms(t::DET_SMOOTH_MS, sample_rate),
            hp_b: 1.0 / (1.0 + k),
            hp_a: (1.0 - k) / (1.0 + k),
            m: 0.0,
            vc: 0.0,
        };
        s.set(DeluxeParams::default());
        s
    }

    #[must_use]
    pub const fn sample_rate(&self) -> f64 {
        self.sample_rate
    }

    pub fn set(&mut self, p: DeluxeParams) {
        let db = |x: f64| libm::pow(10.0, x / 20.0);
        self.crush = db(crush_db(p.crush));
        self.crunch = db(t::CRUNCH_DB_PER_UNIT * p.crunch.clamp(0.0, 10.0));
        let m = (p.mix / 100.0).clamp(0.0, 1.0) * FRAC_PI_2;
        self.wet = libm::sin(m);
        self.dry = libm::cos(m);
        self.rel = pole_ms(if p.release_on { t::DET_TAU_ON_MS } else { t::DET_TAU_OFF_MS }, self.sample_rate);
        // Darkness: crossfade the two measured positions around the knob, in
        // log-Hz. Position 0 is the open knob (identity), then `t::DARK`.
        let hz = p.darkness_hz.clamp(500.0, 20_000.0);
        let at = |i: usize| if i == 0 { 20_000.0 } else { t::DARK.get(i.saturating_sub(1)).map_or(500.0, |q| q.darkness_hz) };
        let mut lo = 0_usize;
        while lo < t::DARK.len().saturating_sub(1) && at(lo.saturating_add(1)) > hz {
            lo = lo.saturating_add(1);
        }
        let (a, b) = (at(lo), at(lo.saturating_add(1)));
        self.pre_lo = lo;
        self.pre_w = if a <= b { 0.0 } else { (libm::log(a / hz) / libm::log(a / b)).clamp(0.0, 1.0) };
    }

    pub fn reset(&mut self) {
        for c in &mut self.ch {
            c.reset();
        }
        self.m = 0.0;
        self.vc = 0.0;
    }

    /// One stereo frame.
    pub fn process(&mut self, left: f64, right: f64) -> (f64, f64) {
        let gr = t::DET_FLOOR_DB - soft_over(t::DET_FLOOR_DB - self.vc, 1.0);
        let g = libm::pow(10.0, -gr / 20.0) * self.crush;
        let (lo, w) = (self.pre_lo, self.pre_w);
        let [cl, cr] = &mut self.ch;
        let dl = g * cl.pre(left);
        let dr = g * cr.pre(right);
        // detector: the stereo sum, rectified and lightly smoothed (a single
        // spike must not charge the cap — the reference shrugs one off),
        // log-compared with θ, integrated on a leaky cap whose voltage is the
        // gain reduction in dB
        self.m += self.smooth * (libm::fabs(0.5 * (dl + dr)) - self.m);
        let level = self.m / self.theta + 1e-12;
        let excess = t::DET_SOFT * soft_over(libm::log(level) / t::DET_SOFT, 1.0);
        // the sidechain's current limit: the cap charges at most this fast
        self.vc = self.vc * self.rel + (self.charge * excess).min(self.charge_max);
        let (wet, dry, hb, ha, k) = (self.wet, self.dry, self.hp_b, self.hp_a, self.crunch);
        let yl = cl.post(curve(k * dl), hb, ha);
        let yr = cr.post(curve(k * dr), hb, ha);
        let (yl, yr) = (cl.dark(yl, lo, w), cr.dark(yr, lo, w));
        (yl * wet + left * dry, yr * wet + right * dry)
    }
}
